import pathlib,json,hashlib
root=pathlib.Path('products')
site=root/'sites/open-software-tenders'
evidence=root/'services/tender-refresh'
result={'site_files':{},'review_material':{},'official_releases':{}}
for p in sorted(site.rglob('*')):
 if p.is_file():
  b=p.read_bytes(); result['site_files'][str(p)]={'sha256':hashlib.sha256(b).hexdigest(),'text':b.decode('utf-8')}
for name in ['index.diff','checks.json','baseline-index.html','verified-source-extract.json']:
 p=evidence/name; result['review_material'][name]=p.read_text()
for name in ['105838-2026','105246-2026']:
 p=evidence/'raw'/f'{name}.json'; b=p.read_bytes(); data=json.loads(b)
 result['official_releases'][name]={'sha256':hashlib.sha256(b).hexdigest(),'releases':data.get('releases',[])}
result['scope']='Independent review material only; no approval, deployment, demand or revenue conclusion yet.'
out=root/'reviews/tender-refresh-independent/material.json'; out.parent.mkdir(parents=True,exist_ok=True); out.write_text(json.dumps(result,ensure_ascii=False,indent=2))
